            "solution": "<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Forms\\Template;\n\nabstract class FormBuilder\n{\n    /**\n     * Template method - final to enforce form render skeleton.\n     */\n    final public function render(array $schema): string\n    {\n        $this->validateSchema($schema);\n        $fields = $this->buildFields($schema);\n        $styled = $this->applyStyling($fields, $schema);\n        $html = $this->renderHtml($styled);\n        $scripts = $this->attachScripts($html);\n        return $scripts;\n    }\n\n    /**\n     * Hook method for validation error handling.\n     */\n    protected function onValidationError(array $errors): void\n    {\n        throw new \\InvalidArgumentException('Form validation failed: ' . implode(', ', $errors));\n    }\n\n    /**\n     * Hook method for custom styling.\n     */\n    protected function applyStyling(array $fields, array $schema): array\n    {\n        foreach ($fields as &$field) {\n            $field['class'] = ($field['class'] ?? '') . ' form-control';\n        }\n        return $fields;\n    }\n\n    /**\n     * Hook method for script attachment.\n     */\n    protected function attachScripts(string $html): string\n    {\n        return $html;\n    }\n\n    abstract protected function validateSchema(array $schema): void;\n    abstract protected function buildFields(array $schema): array;\n    abstract protected function renderHtml(array $fields): string;\n}\n\nclass ContactFormBuilder extends FormBuilder\n{\n    protected function validateSchema(array $schema): void\n    {\n        $required = ['name', 'email', 'message'];\n        $errors = [];\n        foreach ($required as $field) {\n            if (!isset($schema['fields'][$field])) {\n                $errors[] = \"Missing required field: $field\";\n            }\n        }\n        if (!empty($errors)) {\n            $this->onValidationError($errors);\n        }\n    }\n\n    protected function buildFields(array $schema): array\